// v32: Poképédia (https://www.pokepedia.fr, CC BY-NC-SA 3.0 FR) as the primary source of
//   - Pokédex descriptions (per game version, expansions fall back to their base game, per form: headings ==== <form> ==== and regional-form pages),
//   - étymologies (« === Étymologies === »), event distributions (« == Distributions événementielles == »),
//   - detailed capture locations of the Switch-era games (Module:Localisations/Données/<jeu> = data generated by Poképédia from its place
//     articles; incl. gifts « Donné » and in-game trades « Échange »).
// Two steps:  node pokepedia.mjs extract   raw wikitext cache (build/.cache/pokepedia/pages.json, from fetch-pokepedia.py) → build/pokepedia/extract.json.gz (tracked)
//             node pokepedia.mjs apply     extract → docs/data/sp/<id>.json (imported at the end of build-data.mjs; idempotent)
import fs from 'node:fs'; import path from 'node:path'; import zlib from 'node:zlib';
const HERE = path.dirname(new URL(import.meta.url).pathname), D = path.join(HERE, '../docs/data');
const EXTRACT = path.join(HERE, 'pokepedia/extract.json.gz');
const rd = f => JSON.parse(fs.readFileSync(path.join(D, f), 'utf8')), wr = (f, o) => fs.writeFileSync(path.join(D, f), JSON.stringify(o));
const A = s => s.replace(/’/g, "'");
const normF = s => A(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();

// Poképédia {{Jeu|CODE}} → PokéAPI version ids used by core.json games[].ver
export const CODE = { RB: [1, 2], R: [1], B: [2], V: [1], RV: [1, 2], J: [3], OA: [4, 5], O: [4], A: [5], Cr: [6], C: [6], Ru: [7], Sa: [8], RS: [7, 8], 'É': [9], E: [9],
  RFVF: [10, 11], RF: [10], VF: [11], DPP: [12, 13, 14], DP: [12, 13], D: [12], P: [13], Pt: [14], HGSS: [15, 16], HG: [15], SS: [16], NB: [17, 18], N: [17], Bl: [18],
  N2B2: [21, 22], N2: [21], B2: [22], XY: [23, 24], X: [23], Y: [24], RuOSaA: [25, 26], ROSA: [25, 26], RuO: [25], Ruo: [25], SaA: [26], Saa: [26],
  SL: [27, 28], S: [27], L: [28], So: [27], Lu: [28], USUL: [29, 30], US: [29], UL: [30], LGPE: [31, 32], LGP: [31], LGE: [32], EB: [33, 34], Ep: [33], Bo: [34],
  DEPS: [37, 38], DE: [37], PS: [38], LPA: [39], EV: [40, 41], Ec: [40], Vi: [41], LPZA: [47], LPZAmd: [48],
  EC: [40], No: [17], 'Éc': [40], VI: [41], Ev: [40, 41], 'Ép': [33], Bl2: [22], No2: [21] };
// v34: Poképédia article titles of the games (without « Pokémon ») → codes above (older sub-pages link the game instead of {{Jeu|…}})
const GAME_LINK = { 'Rouge': 'R', 'Bleu': 'B', 'Vert': 'V', 'Jaune': 'J', 'Or': 'O', 'Argent': 'A', 'Cristal': 'Cr', 'Rubis': 'Ru', 'Saphir': 'Sa', 'Émeraude': 'É',
  'Rouge Feu': 'RF', 'Vert Feuille': 'VF', 'Rouge Feu et Vert Feuille': 'RFVF', 'Diamant': 'D', 'Perle': 'P', 'Platine': 'Pt', 'Diamant et Perle': 'DP', 'Or HeartGold': 'HG', 'Argent SoulSilver': 'SS',
  'Or HeartGold et Argent SoulSilver': 'HGSS', 'Noir': 'N', 'Blanc': 'Bl', 'Noir et Blanc': 'NB', 'Noir 2': 'N2', 'Blanc 2': 'B2', 'Noir 2 et Blanc 2': 'N2B2', 'X': 'X', 'Y': 'Y', 'X et Y': 'XY',
  'Rubis Oméga': 'RuO', 'Saphir Alpha': 'SaA', 'Rubis Oméga et Saphir Alpha': 'ROSA', 'Soleil': 'S', 'Lune': 'L', 'Soleil et Lune': 'SL', 'Ultra-Soleil': 'US', 'Ultra-Lune': 'UL', 'Ultra-Soleil et Ultra-Lune': 'USUL',
  'Épée': 'Ep', 'Bouclier': 'Bo', 'Épée et Bouclier': 'EB', 'Diamant Étincelant': 'DE', 'Perle Scintillante': 'PS', 'Écarlate': 'Ec', 'Violet': 'Vi', 'Écarlate et Violet': 'EV', 'Légendes Pokémon : Arceus': 'LPA' };
// expansions without their own Pokédex text → base game version
export const EXP = { 42: 40, 52: 41, 43: 40, 53: 41, 35: 33, 50: 34, 36: 33, 51: 34, 48: 47 };

// ---------- wikitext ----------
function stripTemplates(t) {
  // innermost first: {{name|a|b}} → readable text
  for (let i = 0; i < 12 && /\{\{/.test(t); i++) t = t.replace(/\{\{([^{}]*)\}\}/g, (m, body) => {
    const parts = body.split('|'), name = parts[0].trim(), args = parts.slice(1).filter(x => !/^\s*[\w-]+\s*=/.test(x));
    const nm = name.toLowerCase();
    if (nm === 'jeu') return args[0] || '';
    if (nm === 'infobulle' || nm === 'abréviation' || nm === 'abreviation') return args[0] || '';
    if (nm === 'sup' || nm === 'exp') return args[0] || '';
    if (nm === 'e' || nm === 'er' || nm === 're') return { e: 'ᵉ', er: 'ᵉʳ', re: 'ʳᵉ' }[nm];
    if (nm === 'nobr' || nm === 'lang' || nm === 'japonais') return args[args.length - 1] || '';
    return args[0] || '';
  });
  return t;
}
export function clean(t) {
  t = t.replace(/<ref[^>]*\/>/g, '').replace(/<ref[\s\S]*?<\/ref>/g, '').replace(/<!--[\s\S]*?-->/g, '');
  t = t.replace(/\[\[(?:[^\]|]*\|)?([^\]]*)\]\]/g, '$1').replace(/\[https?:[^\s\]]+ ([^\]]*)\]/g, '$1'); // links first: {{PCap|[[Téléport|Teleporter]]}}
  t = stripTemplates(t);
  t = t.replace(/\[\[(?:[^\]|]*\|)?([^\]]*)\]\]/g, '$1');
  t = t.replace(/'''''|'''|''/g, '').replace(/<br\s*\/?>/gi, ' ').replace(/<\/?(?:small|span|sup|sub|u|i|b|nowiki)[^>]*>/gi, '');
  return t.replace(/\s+/g, ' ').replace(/ ([,.])/g, '$1').trim();
}
function section(w, re) { // body of the first heading matching re, up to the next heading of the same or higher level
  const m = w.match(re); if (!m) return null;
  const lvl = m[1].length, rest = w.slice(m.index + m[0].length);
  const end = rest.search(new RegExp(`^={1,${lvl}}[^=]`, 'm'));
  return end >= 0 ? rest.slice(0, end) : rest;
}
const NOTDEX = /En l'absence de Pokédex|absence de Pokédex/i;
function descs(w) {
  const body = section(w, /^(=+) *Descriptions du (?:\[\[)?Pokédex(?:\]\])? *\1 *$/m); if (!body) return [];
  const out = []; let cur = null, form = null;
  for (const line of body.split('\n')) {
    const h = line.match(/^=+ *(.*?) *=+ *$/);
    if (h) { form = clean(h[1]); cur = null; continue; }
    if (line.startsWith(';')) { const codes = [...line.matchAll(/\{\{Jeu\|([^}|]+)/g)].map(x => x[1].trim());
      // v34: games written as links on older-generation sub-pages: « ;{{Jeu|D}}, [[Pokémon Perle|Perle]] et [[Pokémon Platine|Platine]] »
      for (const x of line.matchAll(/\[\[(?:Pokémon )?([^\]|]+?)(?:\|[^\]]*)?\]\]/g)) { const c = GAME_LINK[A(x[1]).trim()]; if (c) codes.push(c); }
      cur = codes.length ? codes : null; }
    else if (line.startsWith(':') && cur) { const t = clean(line.slice(1)); if (t) out.push({ codes: cur, form, t, absent: NOTDEX.test(t) }); }
  }
  return out;
}
function etymology(w) {
  const body = section(w, /^(=+) *[EÉ]tymologies? *\1 *$/m); if (!body) return null;
  const rows = [];
  for (const line of body.split('\n')) { const m = line.match(/^\* *([^:]+?) *: *(.+)$/); if (m) rows.push([clean(m[1]), clean(m[2])]); }
  return rows.length ? rows : null;
}
function events(w) {
  const body = section(w, /^(=+) *Distributions événementielles *\1 *$/m); if (!body) return null;
  const out = []; let year = null;
  for (const line of body.split('\n')) {
    const y = line.match(/^\* *'''(\d{4})'''/); if (y) { year = y[1]; continue; }
    const e = line.match(/^\*\* *(.+)$/); if (e && year) { const t = clean(e[1].replace(/\s*==.*$/, '')); /* v34: heading glued to the last line */ if (t) out.push([year, t]); }
  }
  return out.length ? out : null;
}

// ---------- Lua data tables (Module:Localisations/Données/…) ----------
function parseLua(src) {
  let i = src.indexOf('return'); if (i < 0) throw new Error('no return'); i += 6;
  const ws = () => { for (;;) { while (/\s/.test(src[i])) i++; if (src.startsWith('--', i)) { while (src[i] !== '\n' && i < src.length) i++; } else break; } };
  const str = () => { const q = src[i++]; let s = ''; while (src[i] !== q) { if (src[i] === '\\') { s += src[i + 1]; i += 2; } else s += src[i++]; } i++; return s; };
  function val() {
    ws();
    if (src[i] === '{') {
      i++; const arr = [], obj = {}; let isObj = false;
      for (;;) {
        ws(); if (src[i] === '}') { i++; break; }
        if (src[i] === '[') { i++; ws(); const k = (src[i] === '"' || src[i] === "'") ? str() : num(); ws(); i++; /* ] */ ws(); i++; /* = */ obj[k] = val(); isObj = true; }
        else if (/[A-Za-z_]/.test(src[i]) && /^[A-Za-z_]\w*\s*=/.test(src.slice(i, i + 64))) { const m = src.slice(i).match(/^([A-Za-z_]\w*)\s*=/); i += m[0].length; obj[m[1]] = val(); isObj = true; }
        else arr.push(val());
        ws(); if (src[i] === ',' || src[i] === ';') i++;
      }
      return isObj ? obj : arr;
    }
    if (src[i] === '"' || src[i] === "'") return str();
    if (src.startsWith('true', i)) { i += 4; return true; } if (src.startsWith('false', i)) { i += 5; return false; } if (src.startsWith('nil', i)) { i += 3; return null; }
    return num();
  }
  function num() { const m = src.slice(i).match(/^-?[\d.]+/); i += m[0].length; return +m[0]; }
  return val();
}

// ---------- locations ----------
const LOC_MODULES = { sv: 'Pokémon Écarlate et Violet', za: 'Légendes Pokémon : Z-A', la: 'Légendes Pokémon : Arceus', bdsp: 'Pokémon Diamant Étincelant et Perle Scintillante', sw: 'Pokémon Épée et Bouclier', lgpe: "Pokémon Let's Go, Pikachu et Let's Go, Évoli" };
const VTAG = { Ec: 'Écarlate', Vi: 'Violet', Ep: 'Épée', Bo: 'Bouclier', DE: 'Diamant Étincelant', PS: 'Perle Scintillante', LGP: 'Let’s Go, Pikachu', LGE: 'Let’s Go, Évoli', LPZAmd: 'Méga-Dimension' };
const WEATHER = { 'soleil': 'Soleil', 'pluie': 'Pluie', 'orage': 'Orage', 'soleil-intense': 'Soleil intense', 'tempête-de-sable': 'Tempête de sable', 'nuage': 'Nuageux', 'neige': 'Neige', 'blizzard': 'Blizzard', 'brume': 'Brouillard' };
function gameOfPlace(mod, place, sub, rec) {
  const tx = String(rec.taux || '');
  if (mod === 'sv') return /Septentria/.test(sub || '') ? 'svmask' : /Myrtille|Terra-Dôme/.test(sub || '') ? 'svdisk' : 'sv';
  if (mod === 'sw') return sub === 'Isolarmure' || /Isolarmure/.test(place) ? 'swisle' : sub === 'Couronneige' || /Couronneige/.test(place) ? 'swcrown' : 'sw';
  if (mod === 'za') return sub === 'Extra Illumis' || /LPZAmd/.test(tx) ? 'zadlc' : 'za';
  return mod;
}
function recLine(mod, r) {
  const bits = []; let ver = null;
  const mil = r.milieu ? clean(String(r.milieu)).replace(/,\s*,/g, ',').replace(/,\s*\(/g, ' (').replace(/\s*,\s*$/, '') : '';
  if (mil) bits.push(mil);
  if (r.niveau !== undefined && r.niveau !== '') bits.push('Niv. ' + clean(String(r.niveau)).replace(/-/g, '–'));
  let tx = r.taux !== undefined ? clean(String(r.taux)) : '';
  const vm = tx.match(/,\s*([A-Za-zÉé]+)$/); if (vm && VTAG[vm[1]]) { ver = VTAG[vm[1]]; tx = tx.slice(0, vm.index).trim(); }
  if (tx && tx !== '-' && tx !== '?') bits.push(/^\d+(\.\d+)?$/.test(tx) ? tx + ' %' : tx.charAt(0).toLowerCase() + tx.slice(1));
  for (const [k, lab] of [['taux-matin', 'matin'], ['taux-jour', 'jour'], ['taux-nuit', 'nuit']]) if (r[k] && r[k] !== '-' && r[k] !== '0') bits.push(`${lab} ${clean(String(r[k]))}${/^\d+$/.test(r[k]) ? ' %' : ''}`);
  const wx = Object.entries(WEATHER).filter(([k]) => r['taux-' + k] && r['taux-' + k] !== '-' && r['taux-' + k] !== '0').map(([k, n]) => `${n}${/^\d+$/.test(r['taux-' + k]) ? ' ' + r['taux-' + k] + ' %' : ''}`);
  if (wx.length && wx.length < 9) bits.push('météo : ' + wx.join(', ')); else if (wx.length === 9) bits.push('toutes météos');
  if (r.horaire) bits.push(clean(String(r.horaire)).toLowerCase());
  if (r['météo']) bits.push('météo : ' + clean(String(r['météo'])).toLowerCase());
  const stars = ['1', '2', '3', '4', '5'].filter(k => r[k] && r[k] !== '-' && r[k] !== '0');
  if (stars.length) bits.unshift(`Raid Dynamax ${stars.map(k => k + '★').join(' ')}`);
  if (r['talent-caché'] && mod === 'sw' && /toujours/i.test(r['talent-caché'])) bits.push('talent caché possible');
  if (r['type-téracristal']) bits.push('Téra ' + clean(String(r['type-téracristal'])));
  if (r.difficulté) bits.push(clean(String(r.difficulté)).replace(/^(\d+)$/, '$1★'));
  if (r.notes) bits.push(clean(String(r.notes)));
  if (ver) bits.push(ver);
  return bits.join(' · ');
}

export function extract() {
  const pages = JSON.parse(fs.readFileSync(path.join(HERE, '.cache/pokepedia/pages.json'), 'utf8'));
  const W = t => pages[t] && pages[t].w || '';
  const core = rd('core.json'), base = core.e.filter(e => !e.c);
  const out = { src: 'Poképédia (https://www.pokepedia.fr), CC BY-NC-SA 3.0 FR', date: new Date().toISOString().slice(0, 10), sp: {}, unk: {} };
  const unk = {};
  for (const e of base) {
    const title = A(e.n), main = W(title); if (!main) continue;
    const name = pages[title].t;
    const rec = out.sp[e.id] = {};
    const d = [];
    for (const t of [name, ...Array.from({ length: 8 }, (_, g) => `${name}/Génération ${g + 1}`)]) d.push(...descs(W(t)));
    // regional forms: their own pages (« Raichu d'Alola »)
    for (const f of core.e.filter(x => x.id === e.id && x.c === 'reg')) {
      const pt = A(f.n); const pw = W(pt); if (!pw) continue; const ft = pages[pt].t;
      for (const t of [ft, `${ft}/Génération 7`, `${ft}/Génération 8`]) for (const x of descs(W(t))) d.push({ ...x, fk: f.k });
    }
    const texts = [], tix = new Map(), by = {}; // by[formKeyOr''][ver] = idx | null (absent)
    const forms = core.e.filter(x => x.id === e.id);
    const formKey = h => { if (!h) return ''; const n = normF(h); const f = forms.find(x => x.l && normF(x.l) === n) || forms.find(x => normF(x.n) === n) || forms.find(x => x.l && (normF(x.l).includes(n) || n.includes(normF(x.l)))); return f ? f.k : '?' + h; };
    for (const x of d) {
      const k = x.fk || formKey(x.form);
      for (const c of x.codes) {
        const vs = CODE[c]; if (!vs) { unk[c] = (unk[c] || 0) + 1; continue; }
        for (const v of vs) {
          const m = by[k] ||= {};
          if (m[v] !== undefined) continue;
          if (x.absent) { m[v] = null; continue; }
          if (!tix.has(x.t)) { tix.set(x.t, texts.length); texts.push(x.t); }
          m[v] = tix.get(x.t);
        }
      }
    }
    if (texts.length) { rec.t = texts; rec.v = by; }
    const ety = etymology(main); if (ety) rec.ety = ety;
    const ev = events(main); if (ev) rec.ev = ev;
  }
  // locations
  const subW = W('Module:Localisations/sousZones');
  const subOf = Object.fromEntries([...subW.matchAll(/\["([^"]+)"\] = "([^"]+)"/g)].map(m => [m[1], m[2]]));
  const byName = new Map(); for (const e of base) byName.set(A(e.n), e.id);
  for (const [t, p] of Object.entries(pages)) if (p && !t.startsWith('Module:') && !t.includes('/')) { const id = byName.get(t); if (id && p.t !== t) byName.set(p.t, id); }
  const REG = { Alola: 'alola', Galar: 'galar', Hisui: 'hisui', Paldea: 'paldea' };
  out.loc = {}; const missNames = {};
  for (const [mod, title] of Object.entries(LOC_MODULES)) {
    const src = W('Module:Localisations/Données/' + title); if (!src) { console.log('! module manquant', title); continue; }
    const data = parseLua(src);
    for (const [place, mons] of Object.entries(data)) {
      const sub = subOf[place] || subOf[place.split('@')[0]] || null;
      const placeTxt = clean(place.replace(/\{\{([^{}|]*)$/, (_, x) => x.toLowerCase()).replace(/[^@|{}]*\|/g, '').replace(/@/g, ' — ').replace(/<sup>([^<]*)<\/sup>/g, '$1'));
      for (const [mon, recs] of Object.entries(mons)) {
        const m = mon.match(/^(.*?)(?: (?:forme|sexe|nom)\(([^)]*)\))?$/); let nm = m[1].trim(), form = m[2] || '';
        const id = byName.get(nm); if (!id) { missNames[nm] = (missNames[nm] || 0) + 1; continue; }
        const sex = /sexe\(/.test(mon) ? (form === 'm' ? 'mâle' : form === 'f' ? 'femelle' : form) : '';
        let key = String(id), fl = '';
        if (REG[form]) { const k = `${id}-${REG[form]}`; if (core.e.some(x => x.k === k)) key = k; else fl = form; }
        else if (form && !sex) fl = form;
        for (const r of (Array.isArray(recs) ? recs : [recs])) {
          const g = gameOfPlace(mod, place, sub, r);
          const isRaid = /Cristal de raid|^Antre /.test(place); const r2 = isRaid ? { ...r, difficulté: undefined } : r;
          const line = [fl && `forme ${fl}`, sex, isRaid && mod === 'sv' ? 'Raid Téracristal' : '', recLine(mod, r2) || (isRaid ? '' : 'Sauvage')].filter(Boolean).join(' · ');
          const L = ((out.loc[key] ||= {})[g] ||= []);
          const pl = sub && !/Raid/.test(sub) && !placeTxt.includes(clean(sub)) ? `${placeTxt} (${clean(sub)})` : placeTxt;
          if (!L.some(x => x[0] === pl && x[1] === line)) L.push([pl, line]);
        }
      }
    }
  }
  // « /Indisponibles »: how to get it when it has no location (« Faire évoluer X », « À transférer par HOME »…)
  out.na = {};
  for (const [mod, title] of Object.entries(LOC_MODULES)) {
    const src = W('Module:Localisations/Données/' + title + '/Indisponibles'); if (!src) continue;
    for (const [mon, txt] of Object.entries(parseLua(src))) {
      const m = mon.match(/^(.*?)(?: (?:forme|sexe|nom)\(([^)]*)\))?$/), id = byName.get(m[1].trim()); if (!id || typeof txt !== 'string') continue;
      const k = REG[m[2]] && core.e.some(x => x.k === `${id}-${REG[m[2]]}`) ? `${id}-${REG[m[2]]}` : String(id);
      if (m[2] && !REG[m[2]]) continue; // other forms (Méga…): base entry only
      const tx = clean(txt); if (/^À compléter/i.test(tx) || tx === `Faire évoluer ${m[1].trim()}`) continue; // placeholders / self-references in the source
      (out.na[k] ||= {})[mod] = tx;
    }
  }
  out.unk = { codes: unk, locNames: missNames };
  fs.writeFileSync(EXTRACT, zlib.gzipSync(JSON.stringify(out)));
  const n = Object.values(out.sp);
  console.log(`pokepedia extract: ${n.length} espèces, ${n.filter(x => x.t).length} avec descriptions, ${n.filter(x => x.ety).length} étymologies, ${n.filter(x => x.ev).length} avec distributions, lieux pour ${Object.keys(out.loc).length} entrées`);
  console.log('codes non mappés (jeux hors app) :', Object.entries(unk).sort((a, b) => b[1] - a[1]).slice(0, 30).map(x => x.join('×')).join(' '));
  console.log('noms de lieux non reconnus :', Object.keys(missNames).slice(0, 30).join(', '));
  return out;
}

export function apply() {
  if (!fs.existsSync(EXTRACT)) { console.log('pokepedia apply: pas d’extrait (build/pokepedia/extract.json.gz), ignoré'); return; }
  const X = JSON.parse(zlib.gunzipSync(fs.readFileSync(EXTRACT)));
  const core = rd('core.json'); const ids = [...new Set(core.e.map(e => e.id))];
  const allVer = [...new Set(core.games.flatMap(g => g.ver.map(v => v[0])))];
  let nd = 0, nl = 0, nf = 0;
  for (const id of ids) {
    const f = `sp/${id}.json`, sp = rd(f), r = X.sp[id] || {};
    delete sp.pt; delete sp.pv; delete sp.ety; delete sp.evd;
    for (const v of Object.values(sp.f)) { delete v.pv; delete v.pl; delete v.pln; }
    if (r.t) {
      sp.pt = r.t;
      const fill = m => { const o = {}; for (const [v, i] of Object.entries(m)) if (i !== null) o[v] = i; for (const v of allVer) if (o[v] === undefined && EXP[v] !== undefined && m[EXP[v]] != null) o[v] = m[EXP[v]]; return o; };
      const absent = m => Object.entries(m).filter(([, i]) => i === null).map(([v]) => +v);
      if (r.v['']) { sp.pv = fill(r.v['']); const ab = absent(r.v['']); if (ab.length) sp.pna = ab; else delete sp.pna; nd++; }
      else delete sp.pna;
      for (const [k, m] of Object.entries(r.v)) if (k && !k.startsWith('?') && sp.f[k]) { sp.f[k].pv = fill(m); nf++; if (!sp.pv && k === String(id)) nd++; }
      // unmatched form headings: species-level fallback for versions without text
      for (const [k, m] of Object.entries(r.v)) if (k.startsWith('?')) { const o = fill(m); sp.pv ||= {}; for (const [v, i] of Object.entries(o)) if (sp.pv[v] === undefined) sp.pv[v] = i; }
      if (sp.pv && !Object.keys(sp.pv).length) delete sp.pv;
    } else delete sp.pna;
    if (r.ety) sp.ety = r.ety;
    if (r.ev) sp.evd = r.ev;
    for (const [k, v] of Object.entries(sp.f)) { const L = X.loc[k]; if (L) { v.pl = L; nl++; } const N = (X.na || {})[k]; if (N) v.pln = N; }
    wr(f, sp);
  }
  console.log(`pokepedia apply: descriptions ${nd} espèces (+ ${nf} formes), lieux ${nl} formes`);
}
if (process.argv[1] && process.argv[1].endsWith('pokepedia.mjs')) { const m = process.argv[2]; if (m === 'extract') extract(); else if (m === 'apply') apply(); else if (m === 'all') { extract(); apply(); } else console.log('usage: node pokepedia.mjs extract|apply|all'); }
